import { index, sqliteTable, text } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns, timestampColumns } from "./_shared";

export const OWNERSHIP_HANDOVER_STATUSES = [
  "pending",
  "accepted",
  "declined",
  "canceled",
  "expired",
] as const;

export const ownershipHandovers = sqliteTable(
  "ownership_handovers",
  {
    id: idColumn(),
    ...tenantColumns,
    fromUserId: text("from_user_id").notNull(),
    toUserId: text("to_user_id").notNull(),
    status: text("status", { enum: OWNERSHIP_HANDOVER_STATUSES }).notNull(),
    expiresAt: text("expires_at").notNull(),
    resolvedAt: text("resolved_at"),
    ...timestampColumns,
  },
  (table) => [
    index("ownership_handovers_org_status_idx").on(table.orgId, table.status),
  ],
);

export type OwnershipHandoverRow = typeof ownershipHandovers.$inferSelect;
export type NewOwnershipHandoverRow = typeof ownershipHandovers.$inferInsert;

export * from "./organizations";
export * from "./ownership-handovers";
export * from "./members";

