export async function resolveOrgBySlug(
  slug: string,
): Promise<Organization | null> {
  return orgRepo.findOrgBySlug(slug);
}

function assertRecordedOwner(actor: Actor, org: Organization): void {
  if (actor.userId === org.ownerId) return;
  throw new PermissionDeniedError("org:delete", {
    allowed: false,
    action: "org:delete",
    resourceKind: "organization",
    reason: "denied_by_role",
  });
}

function isOpen(handover: OwnershipHandover, now: Date): boolean {
  return parseIso(handover.expiresAt).getTime() > now.getTime();
}

/**
 * Offers the workspace to an active member. Only the recorded owner may do
 * this, and only while no other offer is still inside its window.
 */
export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  assertRecordedOwner(actor, org);

  if (toUserId === org.ownerId || toUserId === actor.userId) {
    throw new OwnershipHandoverError("self");
  }

  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  const now = new Date();
  const latest = await handoverRepo.findLatestPending(orgId);
  if (latest && isOpen(latest, now)) {
    throw new OwnershipHandoverError("pending_exists");
  }

  const createdAt = toIsoTimestamp(now);
  const handover = await handoverRepo.insertHandover({
    orgId,
    fromUserId: org.ownerId,
    toUserId,
    createdAt,
    expiresAt: addDays(createdAt, HANDOVER_TTL_DAYS),
  });

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "You were offered ownership of this workspace",
    body: "Accept to become the owner. The offer expires in 7 days.",
    href: "/settings/members",
    actorId: actor.userId,
  });

  return handover;
}

/** The open offer, or `null` once it has been resolved or has lapsed. */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);

  const latest = await handoverRepo.findLatestPending(orgId);
  if (!latest || !isOpen(latest, new Date())) return null;
  return latest;
}

/**
 * The offered member becomes the recorded owner and holds the owner role.
 * The previous recorded owner steps down to admin when they still hold the
 * owner role. Promotion happens first so the workspace never has zero owners.
 */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  const now = new Date();
  const offer = await requireOffereeOffer(actor, orgId, now);

  const acceptor = await memberRepo.findMember(orgId, actor.userId);
  if (!acceptor || acceptor.status !== "active") {
    await handoverRepo.resolveHandover(
      orgId,
      offer.id,
      "canceled",
      toIsoTimestamp(now),
    );
    throw new OwnershipHandoverError("nothing_pending");
  }

  const recorded = await memberRepo.findMember(orgId, org.ownerId);
  const changes: { memberId: MemberId; from: Role; to: Role }[] = [];

  if (acceptor.role !== "owner") {
    changes.push({ memberId: acceptor.id, from: acceptor.role, to: "owner" });
  }
  if (
    recorded &&
    recorded.userId !== acceptor.userId &&
    recorded.role === "owner"
  ) {
    changes.push({ memberId: recorded.id, from: recorded.role, to: "admin" });
  }

  for (const change of changes) {
    if (change.to === "owner") {
      await memberRepo.updateMemberRole(orgId, change.memberId, change.to);
    }
  }

  const updated = await orgRepo.updateOrgOwner(orgId, actor.userId);

  for (const change of changes) {
    if (change.to !== "owner") {
      await memberRepo.updateMemberRole(orgId, change.memberId, change.to);
    }
  }

  await handoverRepo.resolveHandover(
    orgId,
    offer.id,
    "accepted",
    toIsoTimestamp(now),
  );

  const occurred = actorEnvelope(actor);
  for (const change of changes) {
    await emit("member.role_changed", {
      ...occurred,
      memberId: change.memberId,
      from: change.from,
      to: change.to,
    });
  }
  await emit("organization.ownership_transferred", {
    ...occurred,
    fromUserId: offer.fromUserId,
    toUserId: offer.toUserId,
  });

  return updated;
}

export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  const now = new Date();
  const offer = await requireOffereeOffer(actor, orgId, now);
  return handoverRepo.resolveHandover(
    orgId,
    offer.id,
    "declined",
    toIsoTimestamp(now),
  );
}

export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  assertRecordedOwner(actor, org);

  const now = new Date();
  const latest = await handoverRepo.findLatestPending(orgId);
  if (!latest || !isOpen(latest, now)) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  return handoverRepo.resolveHandover(
    orgId,
    latest.id,
    "canceled",
    toIsoTimestamp(now),
  );
}

async function requireOffereeOffer(
  actor: Actor,
  orgId: OrgId,
  now: Date,
): Promise<OwnershipHandover> {
  const latest = await handoverRepo.findLatestPending(orgId);
  if (!latest) throw new OwnershipHandoverError("nothing_pending");

  if (!isOpen(latest, now)) {
    if (latest.toUserId === actor.userId) {
      throw new OwnershipHandoverError("expired");
    }
    throw new OwnershipHandoverError("nothing_pending");
  }

  if (latest.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  return latest;
}

