      toIsoTimestamp(now),
    );
    throw new OwnershipHandoverError("nothing_pending");
  }

  const recorded = await memberRepo.findMember(orgId, org.ownerId);
  const changes: { memberId: MemberId; from: Role; to: Role }[] = [];

  if (acceptor.role !== "owner") {
    changes.push({ memberId: acceptor.id, from: acceptor.role, to: "owner" });
  }
  if (
    recorded &&
    recorded.userId !== acceptor.userId &&
    recorded.role === "owner"
  ) {
    changes.push({ memberId: recorded.id, from: recorded.role, to: "admin" });
  }

  for (const change of changes) {
    if (change.to === "owner") {
      await memberRepo.updateMemberRole(orgId, change.memberId, change.to);
    }
  }

  const updated = await orgRepo.updateOrgOwner(orgId, actor.userId);

  for (const change of changes) {
    if (change.to !== "owner") {
      await memberRepo.updateMemberRole(orgId, change.memberId, change.to);
    }
  }

  await handoverRepo.resolveHandover(
    orgId,
    offer.id,
    "accepted",
    toIsoTimestamp(now),
  );

  const occurred = actorEnvelope(actor);
  for (const change of changes) {
    await emit("member.role_changed", {
      ...occurred,
      memberId: change.memberId,
      from: change.from,
      to: change.to,
