 * leaves an audit row in processes that never call `registerEventHandlers`,
 * and again from `registerActivityListeners` — the count guard stops a second
 * registration from writing the transfer twice.
 */
function attachOwnershipAudit(): Unsubscribe {
  if (subscriberCount("organization.ownership_transferred") > 0) {
    return () => undefined;
  }

  return subscribe("organization.ownership_transferred", (payload) =>
