import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { OwnershipHandoverError } from "@/lib/errors";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as memberService from "@/server/services/member-service";
import * as orgService from "@/server/services/organization-service";
import * as billingService from "@/server/services/billing-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("ownership handover", () => {
  it("offers, accepts, and follows the new owner", async () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date("2026-10-01T00:00:00.000Z"));

    const tenant = await createTenant("handover-accept", "growth");
    const admin = tenant.actors.admin;
    const owner = tenant.actors.owner;

    const secondOwnerMember = await memberRepo.findMember(
      tenant.org.id,
      tenant.userIds.member,
    );
    if (!secondOwnerMember) throw new Error("missing");
    await memberService.updateMemberRole(owner, {
      orgId: tenant.org.id,
      memberId: secondOwnerMember.id,
      role: "owner",
    });
    const secondOwner = {
      userId: tenant.userIds.member,
      orgId: tenant.org.id,
      role: "owner" as const,
    };

    await expect(
      orgService.initiateOwnershipHandover(secondOwner, tenant.org.id, admin.userId),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      orgService.initiateOwnershipHandover(owner, tenant.org.id, owner.userId),
    ).rejects.toMatchObject({ reason: "self" });

    await expect(
      orgService.initiateOwnershipHandover(owner, tenant.org.id, tenant.userIds.viewer),
    ).resolves.toBeTruthy();

    // withdraw so we can offer the admin instead
    await orgService.cancelOwnershipHandover(owner, tenant.org.id);

    const events: unknown[] = [];
    const roleEvents: unknown[] = [];
    const offs: Unsubscribe[] = [
      subscribe("organization.ownership_transferred", (payload) => {
        events.push(payload);
      }),
      subscribe("member.role_changed", (payload) => {
        roleEvents.push(payload);
      }),
    ];

    const offer = await orgService.initiateOwnershipHandover(
      owner,
      tenant.org.id,
      admin.userId,
    );

    expect(offer.status).toBe("pending");
    expect(offer.resolvedAt).toBeNull();
    expect(offer.fromUserId).toBe(owner.userId);
    expect(offer.toUserId).toBe(admin.userId);
    expect(offer.expiresAt).toBe("2026-10-08T00:00:00.000Z");
    expect(offer.createdAt).toBe("2026-10-01T00:00:00.000Z");

    await expect(
      orgService.initiateOwnershipHandover(owner, tenant.org.id, tenant.userIds.viewer),
    ).rejects.toMatchObject({ reason: "pending_exists" });

    const seen = await orgService.getPendingOwnershipHandover(
      tenant.actors.viewer,
      tenant.org.id,
    );
    expect(seen?.toUserId).toBe(admin.userId);

    await expect(
      orgService.acceptOwnershipHandover(tenant.actors.viewer, tenant.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });

    await expect(
      orgService.acceptOwnershipHandover(owner, tenant.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });

    const updated = await orgService.acceptOwnershipHandover(admin, tenant.org.id);
    expect(updated.ownerId).toBe(admin.userId);

    const adminMember = await memberRepo.findMember(tenant.org.id, admin.userId);
    const ownerMember = await memberRepo.findMember(tenant.org.id, owner.userId);
    expect(adminMember?.role).toBe("owner");
    expect(ownerMember?.role).toBe("admin");

    expect(events).toHaveLength(1);
    expect(events[0]).toMatchObject({
      actorId: admin.userId,
      fromUserId: owner.userId,
      toUserId: admin.userId,
      orgId: tenant.org.id,
    });
    expect(roleEvents).toEqual(
      expect.arrayContaining([
        expect.objectContaining({
          actorId: admin.userId,
          memberId: adminMember?.id,
          from: "admin",
          to: "owner",
        }),
        expect.objectContaining({
          actorId: admin.userId,
          memberId: ownerMember?.id,
          from: "owner",
          to: "admin",
        }),
      ]),
    );

    const activity = await activityRepo.listActivity({
      orgId: tenant.org.id,
      limit: 20,
      cursor: null,
    });
    const transfer = activity.items.find(
      (row) => row.action === "organization.ownership_transferred",
    );
    expect(transfer).toMatchObject({
      actorId: admin.userId,
      subjectKind: "organization",
      subjectId: tenant.org.id,
      metadata: { fromUserId: owner.userId, toUserId: admin.userId },
    });

    const notes = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: admin.userId,
      unreadOnly: false,
      limit: 20,
      cursor: null,
    });
    expect(notes.items.some((row) => row.kind === "ownership_handover")).toBe(true);
    const ownerNotes = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: owner.userId,
      unreadOnly: false,
      limit: 20,
      cursor: null,
    });
    expect(ownerNotes.items.some((row) => row.kind === "ownership_handover")).toBe(
      false,
    );

    const newOwner = { ...admin, role: "owner" as const };
    const former = { ...owner, role: "admin" as const };

    await expect(
      billingService.changePlan(former, {
        orgId: tenant.org.id,
        plan: "enterprise",
        interval: "monthly",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await billingService.changePlan(newOwner, {
      orgId: tenant.org.id,
      plan: "enterprise",
      interval: "monthly",
    });

    if (!ownerMember) throw new Error("owner missing");
    const removed = await memberService.removeMember(newOwner, {
      orgId: tenant.org.id,
      memberId: ownerMember.id,
    });
    expect(removed.userId).toBe(owner.userId);

    offs.forEach((off) => off());
    vi.useRealTimers();
  });

  it("expires exactly at seven days and does not change the row", async () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date("2026-03-01T12:00:00.000Z"));
    const tenant = await createTenant("handover-expire", "growth");
    const offer = await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.actors.member.userId,
    );

    vi.setSystemTime(new Date("2026-03-08T11:59:59.999Z"));
    await expect(
      orgService.getPendingOwnershipHandover(tenant.actors.viewer, tenant.org.id),
    ).resolves.toMatchObject({ id: offer.id });

    vi.setSystemTime(new Date("2026-03-08T12:00:00.000Z"));
    await expect(
      orgService.getPendingOwnershipHandover(tenant.actors.viewer, tenant.org.id),
    ).resolves.toBeNull();

    await expect(
      orgService.acceptOwnershipHandover(tenant.actors.member, tenant.org.id),
    ).rejects.toMatchObject({ reason: "expired" });
    await expect(
      orgService.declineOwnershipHandover(tenant.actors.member, tenant.org.id),
    ).rejects.toMatchObject({ reason: "expired" });
    await expect(
      orgService.cancelOwnershipHandover(tenant.actors.owner, tenant.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });

    const org = await orgRepo.findOrgById(tenant.org.id);
    expect(org?.ownerId).toBe(tenant.userIds.owner);

    await expect(
      orgService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        tenant.actors.admin.userId,
      ),
    ).resolves.toMatchObject({ status: "pending", toUserId: tenant.userIds.admin });

    vi.useRealTimers();
  });

  it("declines, refuses outsiders, and withdraws when a side leaves", async () => {
    const tenant = await createTenant("handover-decline", "growth");
    const other = await createTenant("handover-other", "growth");

    await expect(
      orgService.initiateOwnershipHandover(
        tenant.actors.owner,
        other.org.id,
        other.actors.admin.userId,
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      orgService.getPendingOwnershipHandover(other.actors.owner, tenant.org.id),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      orgService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        other.actors.admin.userId,
      ),
    ).rejects.toBeInstanceOf(
      (await import("@/server/services/_support")).NotFoundError,
    );

    const removedViewer = await memberRepo.findMember(
      tenant.org.id,
      tenant.userIds.viewer,
    );
    if (!removedViewer) throw new Error("viewer missing");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: removedViewer.id,
    });
    await expect(
      orgService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.viewer,
      ),
    ).rejects.toBeInstanceOf(
      (await import("@/server/services/_support")).NotFoundError,
    );

    const offer = await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.actors.admin.userId,
    );
    const declined = await orgService.declineOwnershipHandover(
      tenant.actors.admin,
      tenant.org.id,
    );
    expect(declined.status).toBe("declined");
    expect(declined.resolvedAt).toEqual(expect.any(String));
    expect((await orgRepo.findOrgById(tenant.org.id))?.ownerId).toBe(
      tenant.userIds.owner,
    );

    await expect(
      orgService.acceptOwnershipHandover(tenant.actors.admin, tenant.org.id),
    ).rejects.toBeInstanceOf(OwnershipHandoverError);

    const again = await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.actors.member.userId,
    );
    expect(again.id).not.toBe(offer.id);

    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    if (!member) throw new Error("member missing");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member.id,
    });
    await expect(
      orgService.getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id),
    ).resolves.toBeNull();
    await expect(
      orgService.acceptOwnershipHandover(tenant.actors.member, tenant.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });
  });

  it("withdraws when the offering owner is removed", async () => {
    const tenant = await createTenant("handover-owner-leaves", "growth");
    const adminMember = await memberRepo.findMember(
      tenant.org.id,
      tenant.userIds.admin,
    );
    if (!adminMember) throw new Error("admin missing");
    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: adminMember.id,
      role: "owner",
    });

    await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.actors.member.userId,
    );

    const ownerMember = await memberRepo.findMember(
      tenant.org.id,
      tenant.userIds.owner,
    );
    if (!ownerMember) throw new Error("owner missing");
    await memberService.removeMember(
      { userId: tenant.userIds.admin, orgId: tenant.org.id, role: "owner" },
      { orgId: tenant.org.id, memberId: ownerMember.id },
    );

    await expect(
      orgService.getPendingOwnershipHandover(tenant.actors.member, tenant.org.id),
    ).resolves.toBeNull();
  });

  it("does not demote a recorded owner who no longer holds the owner role", async () => {
    const tenant = await createTenant("handover-already-admin", "growth");
    const adminMember = await memberRepo.findMember(
      tenant.org.id,
      tenant.userIds.admin,
    );
    const ownerMember = await memberRepo.findMember(
      tenant.org.id,
      tenant.userIds.owner,
    );
    if (!adminMember || !ownerMember) throw new Error("missing");

    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: adminMember.id,
      role: "owner",
    });
    await memberService.updateMemberRole(
      { userId: tenant.userIds.admin, orgId: tenant.org.id, role: "owner" },
      { orgId: tenant.org.id, memberId: ownerMember.id, role: "member" },
    );

    await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.actors.viewer.userId,
    );

    const roleEvents: { memberId: string; from: string; to: string; actorId: string | null }[] =
      [];
    const off = subscribe("member.role_changed", (payload) => {
      roleEvents.push(payload);
    });

    await orgService.acceptOwnershipHandover(tenant.actors.viewer, tenant.org.id);
    off();

    const former = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    expect(former?.role).toBe("member");
    expect(viewer?.role).toBe("owner");
    expect(roleEvents.map((event) => event.memberId)).toEqual([viewer?.id]);
    expect(roleEvents[0]).toMatchObject({
      from: "viewer",
      to: "owner",
      actorId: tenant.userIds.viewer,
    });
    expect((await orgRepo.findOrgById(tenant.org.id))?.ownerId).toBe(
      tenant.userIds.viewer,
    );
  });
});

